// Loopback HTTP supports an explicitly allowed local dev fixture. The gateway
// still checks destination scopes and the dev-only port allowance.
fn valid_endpoint(endpoint: &str) -> bool {
    let Some(canonical) = oauth::canonical_resource(endpoint) else {
        return false;
    };
    if endpoint.contains('#') {
        return false;
    }
    if canonical.starts_with("https://") {
        return true;
    }
    let authority = canonical
        .strip_prefix("http://")
        .and_then(|v| v.split(['/', '?']).next())
        .unwrap_or("");
    let host = authority
        .strip_prefix('[')
        .and_then(|v| v.split(']').next())
        .unwrap_or_else(|| authority.split(':').next().unwrap_or(""));
    host == "127.0.0.1" || host == "::1"
}

