#[cfg(test)]
mod tests {
    use super::*;

    fn request() -> StreamRequest {
        StreamRequest {
            id: 7,
            name: "changed".into(),
            arguments: json!({}),
            cursor: None,
        }
    }
    fn notification(kind: &str, mut params: Value) -> Value {
        params["_meta"] = json!({SUBSCRIPTION:7});
        json!({"jsonrpc":"2.0","method":format!("notifications/events/{kind}"),"params":params})
    }
    fn active() -> Value {
        notification("active", json!({"cursor":"before","truncated":false}))
    }
    fn event() -> Value {
        notification(
            "event",
            json!({"name":"changed","eventId":"id-1","timestamp":"2026-11-05T00:00:00Z","data":{"text":"雪☃"},"cursor":"after"}),
        )
    }
    fn completed() -> Value {
        json!({"jsonrpc":"2.0","id":7,"result":{"resultType":"complete","_meta":{SUBSCRIPTION:7}}})
    }
    fn frame(v: &Value) -> Vec<u8> {
        format!("event: message\r\ndata: {v}\r\n\r\n").into_bytes()
    }
    fn started() -> EventDecoder {
        let mut decoder = EventDecoder::new(&request()).unwrap();
        decoder.push(&frame(&active())).unwrap();
        assert_eq!(decoder.next_message().unwrap().unwrap().kind, "active");
        decoder
    }

    #[test]
    fn events_stream_decodes_every_utf8_and_crlf_boundary_incrementally() {
        let bytes = [frame(&active()), frame(&event()), frame(&completed())].concat();
        for split in 0..=bytes.len() {
            let mut decoder = EventDecoder::new(&request()).unwrap();
            let mut messages = Vec::new();
            for chunk in [&bytes[..split], &bytes[split..]] {
                decoder.push(chunk).unwrap();
                while let Some(message) = decoder.next_message().unwrap() {
                    messages.push(message);
                }
            }
            assert!(decoder.completed());
            decoder.finish().unwrap();
            assert_eq!(messages.len(), 2);
            assert_eq!(messages[1].params["data"]["text"], "雪☃");
            assert_eq!(messages[1].cursor(), Some("after"));
            assert_eq!(messages[1].event_id(), Some("id-1"));
        }
    }

    #[test]
    fn events_stream_yields_before_close_and_preserves_replay_for_durable_dedup() {
        let mut decoder = started();
        let occurrence = frame(&event());
        decoder.push(&occurrence).unwrap();
        let first = decoder.next_message().unwrap().unwrap();
        assert!(!decoder.completed());
        assert!(decoder.finish().is_err());
        let mut resumed = request();
        resumed.id = 8;
        resumed.cursor = first.cursor().map(str::to_string);
        assert_eq!(resumed.envelope().unwrap()["params"]["cursor"], "after");
        decoder.push(&occurrence).unwrap();
        assert_eq!(decoder.next_message().unwrap(), Some(first));
        assert!(decoder.next_message().unwrap().is_none());
    }

    #[test]
    fn events_stream_refuses_wrong_identity_payload_and_terminal_order() {
        let mut bad = Vec::new();
        let mut occurrence = event();
        occurrence["params"]["name"] = json!("other");
        bad.push(occurrence);
        let mut occurrence = event();
        occurrence["params"]["_meta"][SUBSCRIPTION] = json!(8);
        bad.push(occurrence);
        let mut occurrence = event();
        occurrence["params"]["cursor"] = json!(12);
        bad.push(occurrence);
        let mut occurrence = event();
        occurrence["params"]["data"] = json!([]);
        bad.push(occurrence);
        let mut occurrence = event();
        occurrence["params"]["eventId"] = json!("");
        bad.push(occurrence);
        let mut occurrence = event();
        occurrence["params"]["timestamp"] = Value::Null;
        bad.push(occurrence);
        let mut response = completed();
        response["id"] = json!(8);
        bad.push(response);
        let mut response = completed();
        response["result"]["_meta"][SUBSCRIPTION] = json!(8);
        bad.push(response);
        bad.push(notification("unknown", json!({})));
        for bad in bad {
            let mut decoder = started();
            decoder.push(&frame(&bad)).unwrap();
            assert!(decoder.next_message().is_err(), "{bad}");
            assert!(decoder.next_message().is_err());
            assert!(decoder.push(&frame(&event())).is_err());
        }
        let mut decoder = EventDecoder::new(&request()).unwrap();
        decoder.push(&frame(&event())).unwrap();
        assert!(decoder.next_message().is_err());
        let mut decoder = started();
        decoder
            .push(&[frame(&completed()), frame(&event())].concat())
            .unwrap();
        assert!(decoder.next_message().is_err());
    }

    #[test]
    fn events_stream_gap_and_revocation_are_observable_before_completion() {
        let mut decoder = started();
        let messages = [
            notification("active", json!({"cursor":"oldest","truncated":true})),
            notification(
                "error",
                json!({"error":{"code":-32000,"message":"retry later"}}),
            ),
            notification("heartbeat", json!({"cursor":"oldest"})),
            notification(
                "terminated",
                json!({"error":{"code":-32024,"message":"revoked"}}),
            ),
            completed(),
        ];
        for value in messages {
            decoder.push(&frame(&value)).unwrap();
            let result = decoder.next_message().unwrap();
            if value.get("method").is_some() {
                assert_eq!(result.unwrap().params, value["params"]);
            } else {
                assert!(result.is_none());
            }
        }
        assert!(decoder.completed());
        let mut decoder = started();
        decoder
            .push(&frame(&notification(
                "terminated",
                json!({"error":{"code":-32024,"message":"revoked"}}),
            )))
            .unwrap();
        decoder.next_message().unwrap();
        decoder.push(&frame(&event())).unwrap();
        assert!(decoder.next_message().is_err());
    }

    #[test]
    fn events_stream_bounds_partial_frames_and_rejects_truncation() {
        let mut decoder = started();
        decoder.push(&vec![b'a'; MAX_BUFFER_BYTES]).unwrap();
        assert!(decoder.push(b"x").is_err());
        assert!(decoder.next_message().is_err());
        let mut decoder = started();
        decoder.push(b"data: {").unwrap();
        assert!(decoder.finish().is_err());
        let mut decoder = started();
        decoder.push(b"data: \xff\n\n").unwrap();
        assert!(decoder.next_message().is_err());
        let mut decoder = started();
        decoder.push(b": keepalive\n\n").unwrap();
        assert!(decoder.next_message().unwrap().is_none());
        assert!(!decoder.completed());
    }

    #[test]
    fn events_stream_plain_json_refusal_is_correlated() {
        let mut decoder = EventDecoder::new(&request()).unwrap();
        let error = json!({"jsonrpc":"2.0","id":7,"error":{"code":-32024,"message":"Forbidden"}});
        decoder.push(error.to_string().as_bytes()).unwrap();
        assert_eq!(
            decoder.finish(),
            Err(ClientError::Rpc {
                code: -32024,
                message: "Forbidden".into(),
                data: None
            })
        );
        let mut decoder = EventDecoder::new(&request()).unwrap();
        let error = json!({"jsonrpc":"2.0","id":8,"error":{"code":-32024,"message":"Forbidden"}});
        decoder.push(error.to_string().as_bytes()).unwrap();
        assert!(matches!(decoder.finish(), Err(ClientError::Transport(_))));
    }

    #[test]
    fn events_stream_endpoint_keeps_plaintext_to_explicit_loopback() {
        for endpoint in [
            "https://example.com/mcp",
            "http://127.0.0.1:9001/mcp",
            "http://[::1]:9001/mcp",
        ] {
            assert!(valid_endpoint(endpoint), "{endpoint}");
        }
        for endpoint in [
            "http://example.com/mcp",
            "http://127.0.0.1.evil/mcp",
            "http://user@127.0.0.1/mcp",
            "https://example.com/mcp#fragment",
            "http://localhost:9001/mcp",
        ] {
            assert!(!valid_endpoint(endpoint), "{endpoint}");
        }
    }

    #[test]
    fn events_stream_request_binds_profile_name_and_resume_cursor() {
        let mut req = request();
        req.cursor = Some("durable-position".into());
        let envelope = req.envelope().unwrap();
        assert_eq!(
            envelope["params"]["_meta"][proto::META_PROTOCOL_VERSION],
            proto::PROTOCOL_VERSION
        );
        assert_eq!(
            envelope["params"]["_meta"][proto::META_CLIENT_CAPABILITIES]["extensions"][EXTENSION],
            json!({})
        );
        assert_eq!(envelope["params"]["cursor"], "durable-position");
        let headers = req.headers(Some("opaque-secret")).unwrap();
        let value = |name: &str| {
            headers
                .iter()
                .find(|h| h.name.eq_ignore_ascii_case(name))
                .unwrap()
                .value
                .as_str()
        };
        assert_eq!(value("Mcp-Method"), "events/stream");
        assert_eq!(value("Mcp-Name"), "changed");
        assert_eq!(value("Authorization"), "Bearer opaque-secret");
        assert_eq!(value("MCP-Protocol-Version"), proto::PROTOCOL_VERSION);
        assert!(!req
            .headers(None)
            .unwrap()
            .iter()
            .any(|h| h.name.eq_ignore_ascii_case("authorization")));
        assert!(req.headers(Some("bad\r\nheader")).is_err());
        assert!(req.headers(Some("")).is_err());
        req.name = "changed\r\nauthorization: stolen".into();
        assert!(req.envelope().is_err());
        req = request();
        req.arguments = json!([]);
        assert!(req.envelope().is_err());
        req = request();
        req.cursor = Some("x".repeat(4097));
        assert!(req.envelope().is_err());
    }
}
